import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CvydjLy7.js";const m=JSON.parse('{"title":"10.13 问题速查","description":"","frontmatter":{"title":"10.13 问题速查"},"headers":[],"relativePath":"ch10/13.md","filePath":"ch10/13.md","lastUpdated":1789497795000}'),r={name:"ch10/13.md"};function a(n,t,i,s,l,u){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="_10-13-问题速查" tabindex="-1">10.13 问题速查 <a class="header-anchor" href="#_10-13-问题速查" aria-label="Permalink to &quot;10.13 问题速查&quot;">​</a></h1><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>/actuator/metrics</code> 返回 404</td><td>默认只暴露 <code>health</code></td><td>写进 <code>exposure.include</code></td></tr><tr><td><code>include: *</code> 启动就报 YAML 解析失败</td><td><code>*</code> 是 YAML 别名语法</td><td>写成 <code>include: &quot;*&quot;</code></td></tr><tr><td>端点返回 404 而不是 403</td><td>端点没注册路由，不在安全层</td><td>查 <code>exposure.include</code>，别查安全配置</td></tr><tr><td>端点返回 403</td><td>被安全层拦了</td><td>查 <code>SecurityFilterChain</code> 与角色</td></tr><tr><td>找不到符号 <code>HealthIndicator</code></td><td>4.x 换了包与模块</td><td><code>org.springframework.boot.health.contributor</code></td></tr><tr><td>找不到符号 <code>MeterRegistryCustomizer</code></td><td>4.x 换了包</td><td><code>org.springframework.boot.micrometer.metrics.autoconfigure</code></td></tr><tr><td>找不到符号 <code>EndpointRequest</code></td><td>4.x 换了模块与包，旧位置已删除</td><td><code>org.springframework.boot.security.autoconfigure.actuate.web.servlet</code></td></tr><tr><td><code>/actuator/health</code> 只有 <code>{&quot;status&quot;:&quot;UP&quot;}</code></td><td><code>show-details</code> 默认 <code>never</code></td><td>按需改 <code>always</code> 或 <code>when-authorized</code></td></tr><tr><td>配了 <code>info.app.*</code> 但响应里没有 <code>app</code></td><td><code>management.info.env.enabled</code> 默认关</td><td>显式打开</td></tr><tr><td><code>/actuator/info</code> 里没有 <code>build</code> 段</td><td>没有 <code>META-INF/build-info.properties</code></td><td>加 <code>build-info</code> goal</td></tr><tr><td>探针端点 404</td><td><code>probes.enabled</code> 没开</td><td>打开；K8s 里探针要指向 <code>health/liveness</code>、<code>health/readiness</code></td></tr><tr><td>外部依赖抖动导致实例被重启</td><td>liveness 组里塞了外部依赖</td><td>只留 <code>livenessState</code></td></tr><tr><td>就绪组状态是 <code>DOWN</code> 不是 <code>OUT_OF_SERVICE</code></td><td>组状态按包含的组件聚合</td><td>显式配 <code>group.*.status.http-mapping</code></td></tr><tr><td>改级别后日志没变多</td><td><code>effectiveLevel</code> 被父级压住</td><td>看 <code>configuredLevel</code> 与 <code>effectiveLevel</code> 的差异</td></tr><tr><td>读了 <code>configuredLevel</code> 得到 null</td><td><code>null</code> 时该键整个从响应消失</td><td>改成对响应体文本断言</td></tr><tr><td>JsonPath 取不到带点的 logger 名</td><td>点被当成分层</td><td>用 <code>[&#39;com.example.activity&#39;]</code> 写法</td></tr><tr><td><code>curl</code> 查带方括号的 logger 名失败</td><td>方括号被当 glob</td><td>加 <code>-g</code> 或做百分号编码</td></tr><tr><td>列表里有 <code>_org</code> 这种名字</td><td>框架的隐藏 logger，下划线是名字的一部分</td><td>需要时按原样单独调级</td></tr><tr><td><code>Gauge</code> 值是条水平直线</td><td>传了当前值而不是取值函数</td><td>用三参数重载，传 <code>ToDoubleFunction</code></td></tr><tr><td>Prometheus 里多出一条 0 值时间线</td><td>同名 meter 用不同标签组合</td><td>标签组合在构造时一次建全</td></tr><tr><td>看板上指标名对不上</td><td>导出时名字被规范化</td><td>点→下划线、Counter 补 <code>_total</code>、Timer 补 <code>_seconds</code></td></tr><tr><td>测试里 <code>/actuator/prometheus</code> 404、运行时正常</td><td>测试模块默认换掉真实导出</td><td><code>spring.test.metrics.export=true</code></td></tr><tr><td>启动失败提示 <code>management.tracing.enabled</code></td><td>4.x 已废弃且为 error 级</td><td>改成 <code>management.tracing.export.enabled</code></td></tr><tr><td><code>@Observed</code> 不生效</td><td>注解观测默认关闭</td><td><code>management.observations.annotations.enabled=true</code></td></tr><tr><td>Timer 算不出 P99</td><td>没开直方图</td><td><code>management.metrics.distribution.percentiles-histogram.*</code></td></tr><tr><td>时间线数量暴涨</td><td>开了全局直方图或加了高基数标签</td><td>只给关键指标开；标签只用低基数维度</td></tr></tbody></table><hr>',3)])])}const p=d(r,[["render",a]]);export{m as __pageData,p as default};
